// Marks each of the copilot's answers right or wrong against the answer key
// and adds up the score out of 10.
//   Right = exactly the right people (nobody missing, nobody extra), each with their CV.
//   "Nobody matches" questions are right only if the copilot names no one.
//   A person counts only with one of THEIR CV files, so the two Ahmed Hassans can't be mixed up.

const questions = $('Get test questions').all().map((item) => item.json);
const answers = $input.all().map((item) => item.json);

const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const names = (list) => list.map((p) => p.name).join(', ');

const results = questions.map((q, i) => {
  // The answers come back in the same order as the questions; match on the question text to be safe.
  const a = answers.find((x) => norm(x.question) === norm(q.question)) || answers[i] || {};
  const expected = Array.isArray(q.expected) ? q.expected : [];
  const got = (Array.isArray(a.candidates) ? a.candidates : []).map((c) => ({
    name: c.name, cv_file_name: c.cv_file_name || null, score: c.score == null ? null : c.score,
  }));

  // Is this returned person one of the expected people (right name AND one of their CV files)?
  const isExpected = (g, e) => norm(g.name) === norm(e.name)
    && (e.cv_files || [e.cv_file_name]).some((f) => norm(f) === norm(g.cv_file_name));

  let right = false;
  let why;
  if (a.error || !a.status || a.status === 'error') {
    why = 'The copilot gave no answer: ' + (a.error || a.message || 'unknown error');
  } else if (a.status === 'not_a_question') {
    why = 'The copilot did not treat it as a candidate search.';
  } else if (q.expect_no_match) {
    right = got.length === 0;
    why = right ? 'Correctly said nobody matches.' : `Should have found nobody, but named ${names(got)}.`;
  } else {
    const missing = expected.filter((e) => !got.some((g) => isExpected(g, e)));
    const extra = got.filter((g) => !expected.some((e) => isExpected(g, e)));
    right = missing.length === 0 && extra.length === 0;
    const problems = [];
    if (missing.length) problems.push(`missing ${names(missing)}`);
    if (extra.length) problems.push(`should not include ${extra.map((g) => `${g.name} (${g.cv_file_name || 'no CV named'})`).join(', ')}`);
    why = right ? 'Exactly the right people, each with their CV.' : problems.join('; ') + '.';
  }

  return {
    n: q.n,
    question: q.question,
    right,
    why,
    expected: q.expect_no_match ? [] : expected.map((e) => ({ name: e.name, cv_file_name: e.cv_file_name })),
    expect_no_match: q.expect_no_match,
    bot_status: a.status || 'error',
    bot_candidates: got,
    bot_message: a.message || a.error || '',
    search_id: a.search_id || null,
  };
});

const score = results.filter((r) => r.right).length;
const lines = [`🧪 *Copilot test run: ${score}/${results.length}*`];
for (const r of results) {
  lines.push(r.right ? `✅ ${r.n}. ${r.question}` : `❌ ${r.n}. ${r.question}\n      ↳ ${r.why}`);
}

return [{ json: { run: { score, total: results.length, results }, slack_text: lines.join('\n') } }];
